    /// (#task-resource-profile Phase-2a, pair-a) A resource-usage report whose op
    /// is NO LONGER in `running_action_infos` (completion/cancellation raced the
    /// report) must be counted in `profile_samples_skipped_no_action`, not
    /// silently dropped — else the dark-detector invariant breaks.
    ///
    /// MUTATION: drop the `None => { … skipped_no_action.fetch_add }` arm in
    /// `record_action_resource_usage` → counter stays 0 → red-fail.
    #[nativelink_test]
    async fn resource_profile_counts_no_action_skip() {
        use nativelink_proto::com::github::trace_machina::nativelink::remote_execution::ActionResourceUsage;

        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        let _rx_w = add_worker_named(&scheduler, "W", 4).await;

        // Never reserve an action — this op is absent from running_action_infos,
        // so `running_action_info` returns None (the race the counter tracks).
        let missing_op = OperationId::default();
        let usage = ActionResourceUsage {
            peak_memory_kb: 4096,
            sampled: true,
            ..Default::default()
        };
        scheduler
            .record_action_resource_usage(&WorkerId("W".to_string()), &missing_op, usage)
            .await
            .expect("record must return Ok when the op is already gone");

        assert_eq!(
            scheduler.resource_profile_map_len(),
            0,
            "a report for a vanished op must not be folded"
        );
        assert_eq!(
            scheduler
                .metrics
                .profile_samples_skipped_no_action
                .load(Ordering::Relaxed),
            1,
            "profile_samples_skipped_no_action must advance so a completion/cancel \
             race is distinguishable from 'no load'"
        );
    }

    // ── (#task-resource-profile Phase-2b) inject-OBSERVE counterfactual ──

    /// Platform properties carrying a `name` Exact (for capability matching) and a
    /// `memory_kb` Minimum (the reservation the observe reads/reduces).
    fn props_named_with_memory(name: &str, memory_kb: f64) -> PlatformProperties {
        let mut properties = HashMap::new();
        properties.insert(
            "name".to_string(),
            PlatformPropertyValue::Exact(name.to_string()),
        );
        properties.insert(
            "memory_kb".to_string(),
            PlatformPropertyValue::Minimum(memory_kb),
        );
        PlatformProperties { properties }
    }

    async fn add_worker_with_memory(
        scheduler: &Arc<ApiWorkerScheduler>,
        name: &str,
        memory_kb: f64,
    ) -> mpsc::UnboundedReceiver<UpdateForWorker> {
        let (tx, rx) = mpsc::unbounded_channel();
        let worker = Worker::new(
            WorkerId(name.to_string()),
            props_named_with_memory(name, memory_kb),
            tx,
            42,
            0, // max_inflight_tasks = 0 (unlimited), the deployed config
        );
        scheduler.add_worker(worker).await.expect("add_worker");
        rx
    }

    /// (#task-resource-profile Phase-3) Add a worker advertising `memory_kb` remaining
    /// AND a connect-frame `total_memory_kb` (the RAISE starvation-clamp ceiling).
    /// Built via `new_with_cas_endpoint` (unlimited slots, the deployed config).
    async fn add_worker_with_memory_and_total(
        scheduler: &Arc<ApiWorkerScheduler>,
        name: &str,
        memory_kb: f64,
        total_memory_kb: u64,
    ) -> mpsc::UnboundedReceiver<UpdateForWorker> {
        let (tx, rx) = mpsc::unbounded_channel();
        let worker = Worker::new_with_cas_endpoint(
            WorkerId(name.to_string()),
            props_named_with_memory(name, memory_kb),
            tx,
            42,
            0, // max_inflight_tasks = 0 (unlimited)
            String::new(),
            0,
            0,
            total_memory_kb,
        );
        scheduler.add_worker(worker).await.expect("add_worker");
        rx
    }

    /// Build an action requiring `declared_kb` memory on worker `name`, carrying the
    /// Bazel baggage the profile key derives from (`//foo:bar` / `CppCompile`).
    fn action_with_memory_and_baggage(name: &str, seed: u8, declared_kb: f64) -> ActionInfoWithProps {
        use nativelink_proto::build::bazel::remote::execution::v2::RequestMetadata;
        use nativelink_util::origin_event::OriginMetadata;

        let mut action = make_action_info_with_props(name, seed);
        action.platform_properties = props_named_with_memory(name, declared_kb);
        action.origin_metadata = OriginMetadata {
            identity: String::new(),
            bazel_metadata: Some(RequestMetadata {
                action_mnemonic: "CppCompile".to_string(),
                target_id: "//foo:bar".to_string(),
                ..Default::default()
            }),
        };
        action
    }

    /// The observe key for `action_with_memory_and_baggage` (instance "main" comes
    /// from `make_action_info_with_props`'s unique_qualifier).
    fn observe_key() -> crate::resource_profile::ProfileKey {
        crate::resource_profile::ProfileKey::from_parts("main", "//foo:bar", "CppCompile").unwrap()
    }

    fn mem_only_sample(memory_kb: u64) -> crate::resource_profile::ResourceSample {
        crate::resource_profile::ResourceSample {
            memory_kb,
            cpu_ns: 0,
            disk_bytes: 0,
            net_bytes: 0,
        }
    }

    /// THE load-bearing observe-only contract: with a ≥K-sample profile whose
    /// tail-aware memory statistic FAR exceeds the action's declared `memory_kb`,
    /// the dispatch computes the counterfactual raise (`would_raise` fires) yet the
    /// actual reservation is BYTE-IDENTICAL to the no-injection path — the worker's
    /// remaining `memory_kb` reflects the DECLARED value subtracted, never the tail.
    ///
    /// MUTATION A (counter): comment out the `inject_observe_would_raise.fetch_add`
    /// → the would_raise assert red-fails.
    /// MUTATION B (observe-only broken): if the observe were changed to APPLY the
    /// raise to the reserved worker, the remaining-memory assert red-fails (it would
    /// read `capacity − would_raise_to`, not `capacity − declared`).
    #[nativelink_test]
    async fn inject_observe_raise_only_never_mutates_reservation() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        let _rx_w = add_worker_with_memory(&scheduler, "W", 100_000.0).await;

        // Pre-populate a reliable (≥K) profile whose tail exceeds declared. 50_000
        // KiB → bucket 16 [2^15,2^16) → tail 2^16 = 65_536 ≫ declared 4096.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(50_000));
        }
        assert_eq!(
            scheduler.resource_profile_map_len(),
            1,
            "profile must be pre-populated before dispatch"
        );

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xc1, 4096.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 4096.0), &op, &action, false)
            .await
            .expect("op must reserve worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        // The observe ran and SAW a raise (tail 65536 > declared 4096).
        assert_eq!(
            scheduler.metrics.inject_observe_total.load(Ordering::Relaxed),
            1,
            "inject_observe_total must advance once per reserved dispatch"
        );
        assert_eq!(
            scheduler
                .metrics
                .inject_observe_would_raise
                .load(Ordering::Relaxed),
            1,
            "the profiled tail (65536) exceeds declared (4096) → inject_observe_would_raise \
             must fire (the counterfactual computed a raise)"
        );

        // THE contract: the reservation is UNCHANGED. Worker W had 100_000 KiB; the
        // action declared 4096 → remaining must be 100_000 − 4096 = 95_904, NOT
        // 100_000 − 65_536 (the would-raise value). Observe changed no reservation.
        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(95_904.0),
            "OBSERVE-ONLY VIOLATED: worker remaining memory_kb must reflect the DECLARED \
             4096 subtracted (95904), not the counterfactual tail 65536 — the inject-observe \
             phase must change NO reservation"
        );
    }

    /// declared > tail → RAISE-ONLY yields no raise: the counterfactual would_raise_to
    /// equals declared, so `inject_observe_would_raise` does NOT fire even though a
    /// reliable profile is present (the residual observed-non-raise case).
    ///
    /// MUTATION: change `would_raise_to = declared_kb.max(tail_kb)` to `tail_kb`
    /// (drop the raise-only floor) → declared 100_000 > tail 65_536 would then read a
    /// LOWER value ≠ declared → `delta_kb > 0` → would_raise fires → this test red-fails.
    #[nativelink_test]
    async fn inject_observe_declared_above_tail_does_not_raise() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        let _rx_w = add_worker_with_memory(&scheduler, "W", 200_000.0).await;

        // Tail 65_536 (from 50_000-KiB samples) is BELOW the declared 100_000.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(50_000));
        }

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xc2, 100_000.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 100_000.0), &op, &action, false)
            .await
            .expect("op must reserve worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        assert_eq!(
            scheduler.metrics.inject_observe_total.load(Ordering::Relaxed),
            1
        );
        assert_eq!(
            scheduler
                .metrics
                .inject_observe_would_raise
                .load(Ordering::Relaxed),
            0,
            "declared (100000) exceeds the profiled tail (65536) → RAISE-ONLY yields no \
             raise → inject_observe_would_raise must stay 0"
        );
        assert_eq!(
            scheduler
                .metrics
                .inject_observe_skipped_low_sample
                .load(Ordering::Relaxed),
            0,
            "the profile has ≥K samples → NOT a low-sample skip"
        );
    }

    /// A profile present but with `< K` samples must NOT be trusted: the observe
    /// counts `inject_observe_skipped_low_sample` and computes no raise (a
    /// freshly-LRU-re-admitted key is low-sample; pair-a MINOR / A1b K-gate).
    ///
    /// MUTATION: comment out the `samples < PROFILE_MIN_SAMPLES` early-return →
    /// the 1-sample tail (65536 > 4096) would fire would_raise → this test red-fails
    /// (skipped_low_sample stays 0 AND would_raise becomes 1).
    #[nativelink_test]
    async fn inject_observe_skips_low_sample() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        let _rx_w = add_worker_with_memory(&scheduler, "W", 100_000.0).await;

        // Only ONE sample — below K = PROFILE_MIN_SAMPLES (20).
        scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(50_000));

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xc3, 4096.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 4096.0), &op, &action, false)
            .await
            .expect("op must reserve worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        assert_eq!(
            scheduler
                .metrics
                .inject_observe_skipped_low_sample
                .load(Ordering::Relaxed),
            1,
            "a profile with < K samples must be counted skipped_low_sample (tail untrusted)"
        );
        assert_eq!(
            scheduler
                .metrics
                .inject_observe_would_raise
                .load(Ordering::Relaxed),
            0,
            "a low-sample key must never compute a counterfactual raise"
        );
    }

    /// No usable profile (empty map — the Phase-2a-just-deployed norm): the observe
    /// counts `inject_observe_skipped_no_profile` and computes no raise.
    ///
    /// MUTATION: comment out the `peek_memory_tail(...) else` skip-return → a `None`
    /// tail would flow on and panic/misbehave; with the skip, the counter fires and
    /// would_raise stays 0. (Also proves the empty-map dispatch is safe.)
    #[nativelink_test]
    async fn inject_observe_skips_no_profile() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        let _rx_w = add_worker_with_memory(&scheduler, "W", 100_000.0).await;

        // NO profile pre-populated — the map is empty.
        assert_eq!(scheduler.resource_profile_map_len(), 0);

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xc4, 4096.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 4096.0), &op, &action, false)
            .await
            .expect("op must reserve worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        assert_eq!(
            scheduler
                .metrics
                .inject_observe_skipped_no_profile
                .load(Ordering::Relaxed),
            1,
            "an unprofiled key (empty map) must be counted skipped_no_profile"
        );
        assert_eq!(
            scheduler
                .metrics
                .inject_observe_would_raise
                .load(Ordering::Relaxed),
            0,
            "no profile → no counterfactual raise"
        );
        // The reservation still happened normally: worker remaining = 100000 − 4096.
        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(95_904.0),
            "the observe skip must not disturb the normal reservation"
        );
    }

    /// (#task-resource-profile Phase-3 §4) DOWN-OPPORTUNITY observe metric: when a
    /// trusted (≥K) profile's p50 sits BELOW the client-declared `memory_kb`, the
    /// dispatch folds `declared*100/p50` (×100) into the `down_opportunity_*`
    /// aggregate — the REAL DOWN headroom the cadre C4 said was missing. 20 samples
    /// @2000 KiB → window p50 = 2000 (exact raw); declared 15_360 → ratio 768 (7.68×),
    /// tier Fine. No raise fires (declared > p95 2000), so this is a pure DOWN case.
    ///
    /// MUTATION: comment out `down_opportunity_samples.fetch_add` in
    /// `observe_inject_counterfactual` → `down_opportunity_samples` stays 0 → the
    /// samples assert red-fails with its bespoke message.
    #[nativelink_test]
    async fn down_opportunity_metric_folds_declared_over_p50() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        let _rx_w = add_worker_with_memory(&scheduler, "W", 100_000.0).await;

        // Pre-populate a trusted (≥K) profile whose p50 (2000) sits well BELOW the
        // declared 15_360 — a genuine DOWN-overcommit opportunity.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(2000));
        }

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xdb, 15_360.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 15_360.0), &op, &action, false)
            .await
            .expect("op must reserve worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        assert_eq!(
            scheduler.metrics.down_opportunity_samples.load(Ordering::Relaxed),
            1,
            "a trusted (≥K) dispatch with declared>p50 must fold exactly one \
             down_opportunity sample"
        );
        assert_eq!(
            scheduler.metrics.down_opportunity_sum_x100.load(Ordering::Relaxed),
            768,
            "down_opportunity = declared*100/p50 = 15360*100/2000 = 768 (7.68×) must be \
             summed — this is the REAL DOWN headroom (declared vs the p50 central estimate)"
        );
        assert_eq!(
            scheduler.metrics.down_opportunity_max_x100.load(Ordering::Relaxed),
            768,
            "the single sample's ratio (768) must set the max gauge"
        );
        assert_eq!(
            scheduler.metrics.down_opportunity_fine_samples.load(Ordering::Relaxed),
            1,
            "the trusted profile resolved to the FINE tier → the fine subset counter must fire"
        );
        assert_eq!(
            scheduler.metrics.down_opportunity_coarse_samples.load(Ordering::Relaxed),
            0,
            "no coarse fallback occurred → the coarse subset must stay 0 (fine+coarse==samples)"
        );
        // The RAISE-side would_raise must NOT fire: declared 15360 > tail 2000, so this
        // is a pure DOWN opportunity, cleanly separated from the RAISE signal.
        assert_eq!(
            scheduler.metrics.inject_observe_would_raise.load(Ordering::Relaxed),
            0,
            "declared (15360) exceeds the tail (2000) → no raise; DOWN opportunity only"
        );
    }

    /// (#2497 p95 policy) THE observe/enforce-consistency discriminator: a SPREAD window
    /// whose MAX exceeds declared but whose P95 is at/under declared must count as a
    /// DOWN-opportunity (p95 <= declared), NOT a would-raise — because the enforce phase
    /// reserves on p95, so the observe counterfactual must too. Under the old max-based
    /// observe this same key counted as would_raise (max > declared), the exact
    /// inconsistency this change removes.
    ///
    /// Window = 19 @ 10_000 + 1 @ 500_000: max 500_000, p95 10_000, p50 10_000. Declared
    /// 50_000 → max (500_000) > declared but p95 (10_000) <= declared.
    ///
    /// MUTATION: key the observe on `memory_tail_kb` (max) instead of `p95_kb` → max
    /// 500_000 > declared 50_000 → would_raise fires (1) and down_opportunity stays 0 →
    /// BOTH asserts red-fail.
    #[nativelink_test]
    async fn observe_keys_on_p95_not_max_spread_window() {
        let scheduler = build_scheduler(BarrierWorkerStateManager::new());
        let _rx_w = add_worker_with_memory(&scheduler, "W", 1_000_000.0).await;

        // A K-mature SPREAD window: 19 low + 1 high, so max ≫ p95.
        for _ in 0..(crate::resource_profile::PROFILE_MIN_SAMPLES - 1) {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(10_000));
        }
        scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(500_000));

        // The window MAX is above declared (the discriminator: max-based observe would raise).
        assert_eq!(
            scheduler.resource_profile_peek_tail(&observe_key()).map(|(t, _)| t),
            Some(500_000),
            "window max must be 500_000 (> declared 50_000) — the old max-based observe would \
             have counted this as would_raise"
        );

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xda, 50_000.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 50_000.0), &op, &action, false)
            .await
            .expect("op must reserve worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        assert_eq!(
            scheduler.metrics.inject_observe_would_raise.load(Ordering::Relaxed),
            0,
            "p95 (10_000) <= declared (50_000) → the observe must NOT count would_raise, even \
             though the window MAX (500_000) exceeds declared — the observe keys on p95, not max"
        );
        assert_eq!(
            scheduler.metrics.down_opportunity_samples.load(Ordering::Relaxed),
            1,
            "p95 <= declared → this is the DOWN side: down_opportunity must fire exactly once"
        );
        assert_eq!(
            scheduler.metrics.down_opportunity_sum_x100.load(Ordering::Relaxed),
            500,
            "down_opportunity = declared*100/p50 = 50_000*100/10_000 = 500 (p50 is the exact \
             10_000 low mode)"
        );
    }

    // ── (#task-resource-profile Phase-3 §5/§7) RAISE + store-once ledger ──

    /// (§7 RAISE + §5 store-once; #2497 p95 policy) With RAISE enabled and a trusted (≥K)
    /// profile whose p95 (50_000) EXCEEDS the declared `memory_kb` (4096), the reservation
    /// reserves the P95, and — the store-once contract — the worker's remaining `memory_kb`
    /// is decremented by the EFFECTIVE (50_000), never the declared (4096). Worker RAM
    /// (100_000 total + remaining) is large enough that no clamp fires.
    ///
    /// MUTATION: in `find_and_reserve_worker`, pass the ORIGINAL `action_info` (not
    /// `sel_action_info`) to `inner_find_and_reserve_worker` → reduce/store use the
    /// declared 4096 while the gate used the effective → remaining reads 95_904 (=
    /// 100_000 − 4096) → this red-fails (the reduce/gate split that breaks store-once).
    #[nativelink_test]
    async fn raise_reserves_the_tail_via_store_once_ledger() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        scheduler.set_phase3_enforcement(true, false, 1.0, 604_800, false, 2000, 20000, false); // RAISE on
        let _rx_w = add_worker_with_memory_and_total(&scheduler, "W", 100_000.0, 200_000).await;

        // Trusted (≥K) profile: 20 @ 50_000 KiB → window p95 = 50_000 ≫ declared 4096.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(50_000));
        }

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xf1, 4096.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 4096.0), &op, &action, false)
            .await
            .expect("RAISE-reserved op must land on worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(100_000.0 - 50_000.0),
            "RAISE must reserve the EFFECTIVE p95 (50_000) via the store-once ledger — the \
             worker's remaining memory_kb must be 100_000−50_000=50_000, NOT 100_000−4096 \
             (which would mean the gate saw the raise but reduce/store saw the declared)"
        );
    }

    /// (§5 store-once SYMMETRY, the 2026-05-08 trap; #2497 p95 policy) reduce and restore
    /// must be symmetric EVEN when the profile map mutates MID-ACTION. Reserve with RAISE
    /// (p95 50_000), then fold NEW higher samples (window p95/max jumps to 5_000_000) — a
    /// recompute at restore would add back the NEW value — then complete the action: the
    /// worker's remaining memory_kb must return to the EXACT baseline (100_000), because
    /// restore reads the STORED effective (50_000), never a recomputed value.
    ///
    /// MUTATION: in `find_and_reserve_worker`, pass the ORIGINAL `action_info` to
    /// `inner_find_and_reserve_worker` → the post-reserve remaining assert (50_000)
    /// red-fails (store-once write bypassed). [The post-complete baseline holds by
    /// construction: restore reads the stored clone, so no map mutation can drift it.]
    #[nativelink_test]
    async fn raise_reduce_restore_symmetric_under_midaction_map_mutation() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        scheduler.set_phase3_enforcement(true, false, 1.0, 604_800, false, 2000, 20000, false);
        let _rx_w = add_worker_with_memory_and_total(&scheduler, "W", 100_000.0, 200_000).await;

        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(50_000));
        }

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xf2, 4096.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 4096.0), &op, &action, false)
            .await
            .expect("RAISE-reserved op must land on worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));
        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(50_000.0),
            "after reserve the remaining must be 100_000−50_000 (the STORED effective p95)"
        );

        // MID-ACTION map mutation: fold 20 higher samples so the window fully turns over to
        // 5_000_000 (max/p95 = 5_000_000). A restore that RECOMPUTED would add that back.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(5_000_000));
        }
        assert_eq!(
            scheduler.resource_profile_peek_tail(&observe_key()).map(|(t, _)| t),
            Some(5_000_000),
            "the mid-action fold must have raised the key's window max (to 5_000_000) so a \
             recompute-at-restore would drift the ledger — the setup for the trap"
        );

        // Complete the action → restore_platform_properties(stored props) adds back the
        // STORED 65_536, never the now-larger recomputed tail.
        {
            let mut inner = scheduler.inner.write().await;
            let w = inner
                .workers
                .0
                .peek_mut(&WorkerId("W".to_string()))
                .expect("worker W present");
            w.complete_action(&op).expect("complete_action must restore");
        }
        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(100_000.0),
            "STORE-ONCE SYMMETRY: after completion the remaining must return to the EXACT \
             baseline (100_000). A recompute-at-restore from the mutated map would add back \
             the NEW tail (2^23) and drift the ledger — the 2026-05-08 phantom-FULL trap"
        );
    }

    /// (§7 RAISE starvation clamp, C5; #2497 p95 policy) When the raised value exceeds
    /// EVERY worker's total RAM, RAISE clamps to the max worker capacity so the action
    /// stays schedulable rather than stranding forever. Worker total = remaining =
    /// 8_000_000; profile p95 (10_000_000) > total; declared 4_000_000. The clamp brings
    /// effective down to 8_000_000, which the worker CAN satisfy → the op reserves.
    ///
    /// MUTATION: delete the `max_total > 0 && reserve_kb > max_total` clamp branch in
    /// `phase3_starvation_clamp` (return `reserve_kb` unconditionally) → effective
    /// 10_000_000 > 8_000_000 remaining → `is_satisfied_by` fails → NO worker → the reserve
    /// returns None → the "must not strand" expect red-fails with its bespoke message.
    #[nativelink_test]
    async fn raise_clamps_to_max_worker_total_not_strand() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        scheduler.set_phase3_enforcement(true, false, 1.0, 604_800, false, 2000, 20000, false);
        // Worker total RAM 8_000_000; advertises 8_000_000 remaining.
        let _rx_w =
            add_worker_with_memory_and_total(&scheduler, "W", 8_000_000.0, 8_000_000).await;

        // Trusted profile: 20 @ 10_000_000 KiB → window p95 = 10_000_000 > total.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(10_000_000));
        }

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xf3, 4_000_000.0);
        let reserve = scheduler
            .find_and_reserve_worker(
                &props_named_with_memory("W", 4_000_000.0),
                &op,
                &action,
                false,
            )
            .await;
        let (reserved, _tx, _msg) = reserve.expect(
            "RAISE must CLAMP the raised reservation (p95 10_000_000) down to the max worker \
             total (8_000_000) so the action stays schedulable — it must NOT strand above \
             every worker's RAM",
        );
        assert_eq!(reserved, WorkerId("W".to_string()));
        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(0.0),
            "the clamped effective (8_000_000) must be reserved in full → remaining 0"
        );
    }

    // ── (#task-resource-profile Phase-3 §3) DOWN-overcommit ──

    /// (§3; #2497 p95 policy) The DOWN reserve function: reserve the p95, clamped into
    /// `[declared/max_factor, declared]` (the profile-independent floor).
    ///
    /// MUTATION: change the clamp low bound from `floor` to `0` → the tiny-p95 floor case
    /// red-fails (reserve collapses to the raw p95 instead of the floor).
    #[test]
    fn phase3_down_effective_kb_p95_and_floor() {
        // Reserve the p95 when it is above the floor. declared 100_000, p95 50_000,
        // factor 4 → floor 25_000 → reserve 50_000.
        assert_eq!(
            phase3_down_effective_kb(100_000, 50_000, 4.0),
            50_000,
            "the DOWN reserve is the p95 (50_000) when it sits above the floor (declared/4 = 25_000)"
        );

        // FLOOR RESPECTED: a tiny p95 (384) must NOT drive the reserve below the
        // profile-independent floor. factor 2 → floor 50_000 → clamp up to 50_000.
        assert_eq!(
            phase3_down_effective_kb(100_000, 384, 2.0),
            50_000,
            "the floor declared/max_factor (100_000/2 = 50_000) must bound a wrong-low \
             reserve: p95 384 is clamped UP to 50_000, so a single bad prediction \
             under-reserves by at most the factor"
        );

        // A higher factor lets the p95 pack lower. declared 100_000, p95 10_000, factor 10
        // → floor 10_000 → reserve 10_000 (p95 == floor here).
        assert_eq!(
            phase3_down_effective_kb(100_000, 10_000, 10.0),
            10_000,
            "with factor 10 the floor is declared/10 = 10_000; a p95 of 10_000 packs to 10_000"
        );

        // INERT at factor 1.0: floor == declared → clamp pins effective at declared.
        assert_eq!(
            phase3_down_effective_kb(100_000, 384, 1.0),
            100_000,
            "factor 1.0 (the default kill-dial) makes the floor == declared → DOWN is \
             INERT (reserves the declared value, no overcommit)"
        );
    }

    /// (#task-memgate-twosignal, deliverable (c)) The reactive churn-throttle:
    /// a HIGH candidate/fleet churn scalar drives the effective factor toward 1.0
    /// (no overcommit); a LOW churn keeps the full factor; the band interpolates.
    /// Composed with `phase3_down_effective_kb` to show the end effect: high churn
    /// → effective reservation == declared (no overcommit).
    ///
    /// MUTATION (CLAUDE.md TDD #5): make `phase3_churn_throttled_factor` IGNORE the
    /// churn (e.g. always `return base_factor`) → the high-churn assertion red-fails
    /// with its bespoke message (factor stays 2.0 → overcommit not backed off).
    #[test]
    fn churn_throttle_backs_off_overcommit_at_high_churn() {
        let (low, high) = (2_000u32, 20_000u32);
        // Below the band → FULL factor.
        assert!(
            (phase3_churn_throttled_factor(2.0, 0, low, high, true) - 2.0).abs() < 1e-9,
            "churn at/below `low` must keep the FULL overcommit factor"
        );
        assert!(
            (phase3_churn_throttled_factor(2.0, low, low, high, true) - 2.0).abs() < 1e-9,
            "churn exactly at `low` still keeps the FULL factor"
        );
        // At/above the band → 1.0 (no overcommit).
        let hi_factor = phase3_churn_throttled_factor(2.0, high, low, high, true);
        assert!(
            (hi_factor - 1.0).abs() < 1e-9,
            "a HIGH churn ({high}) must back the effective factor down to 1.0 (no \
             overcommit): got {hi_factor}. If this reads 2.0, the throttle ignored \
             the churn scalar (deliverable c)"
        );
        assert!(
            (phase3_churn_throttled_factor(2.0, 100_000, low, high, true) - 1.0).abs() < 1e-9,
            "churn above `high` clamps to 1.0"
        );
        // Midpoint → halfway (2.0 → 1.0 at churn = (low+high)/2 = 11000 → 1.5).
        let mid = phase3_churn_throttled_factor(2.0, 11_000, low, high, true);
        assert!(
            (mid - 1.5).abs() < 1e-9,
            "the band interpolates LINEARLY: churn at the midpoint yields the \
             midpoint factor (2.0→1.0 ⇒ 1.5); got {mid}"
        );

        // End effect through the reservation: at HIGH churn the effective factor is
        // 1.0 → the DOWN floor == declared → NO overcommit (reserve == declared).
        assert_eq!(
            phase3_down_effective_kb(100_000, 384, hi_factor),
            100_000,
            "with the factor throttled to 1.0 by high churn, the DOWN reserve equals \
             declared (100_000) — overcommit is fully backed off on a thrashing fleet"
        );
        // At LOW churn the full factor (2.0) floors at declared/2 = 50_000.
        assert_eq!(
            phase3_down_effective_kb(
                100_000,
                384,
                phase3_churn_throttled_factor(2.0, 0, low, high, true),
            ),
            50_000,
            "with low churn the full factor (2.0) still overcommits down to \
             declared/2 = 50_000"
        );
    }

    /// (#task-memgate-twosignal, deliverable (d)) Throttle flag OFF → the effective
    /// factor equals the static `phase3_overcommit_max_factor`, BYTE-IDENTICAL to
    /// the pre-throttle DOWN path, regardless of how high the churn is.
    ///
    /// MUTATION (CLAUDE.md TDD #5): make `phase3_churn_throttled_factor` ignore the
    /// `enabled` flag (drop the `!enabled` guard) → with a huge churn the returned
    /// factor collapses to 1.0 ≠ 2.0 → this test red-fails.
    #[test]
    fn churn_throttle_off_is_byte_identical_static_factor() {
        // Even a churn far above the band leaves the factor at the static 2.0 when
        // the throttle is DISABLED.
        for churn in [0u32, 2_000, 20_000, u32::MAX] {
            let f = phase3_churn_throttled_factor(2.0, churn, 2_000, 20_000, false);
            assert!(
                (f - 2.0).abs() < 1e-9,
                "throttle OFF must return the STATIC factor 2.0 unchanged (churn={churn}), \
                 byte-identical to the pre-throttle path; got {f}. If this differs, the \
                 `!enabled` early-return was dropped (deliverable d)"
            );
        }
        // The degenerate-band + factor<=1.0 guards also return base unchanged.
        assert!(
            (phase3_churn_throttled_factor(2.0, 50_000, 20_000, 2_000, true) - 2.0).abs() < 1e-9,
            "an inverted band (high <= low) must not silently zero overcommit — return base"
        );
        assert!(
            (phase3_churn_throttled_factor(1.0, u32::MAX, 2_000, 20_000, true) - 1.0).abs() < 1e-9,
            "factor 1.0 (DOWN inert) is unaffected by the throttle"
        );
    }

    /// (§3 integration, requirement c: DOWN floor respected) With DOWN enabled and an
    /// over-declared key (tiny p50 384, tail 512 <= declared 100_000), the reservation
    /// is floored at `declared / overcommit_max_factor` (100_000/2 = 50_000), NOT the
    /// tiny p50 — so the worker's remaining memory drops by exactly 50_000.
    ///
    /// MUTATION: change the clamp in `phase3_down_effective_kb` from
    /// `reserve.clamp(floor, declared_kb)` to `reserve.min(declared_kb)` (drop the
    /// floor) → effective becomes 384 → remaining reads 199_616 → this red-fails.
    #[nativelink_test]
    async fn down_overcommit_floor_respected_at_max_factor() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        scheduler.set_phase3_enforcement(false, true, 2.0, 604_800, false, 2000, 20000, false); // DOWN on, factor 2.0
        let _rx_w = add_worker_with_memory_and_total(&scheduler, "W", 200_000.0, 200_000).await;

        // Over-declared key: 20 samples @ 500 KiB → window p95 = 500 <= declared 100_000
        // (so the DOWN branch fires), tight window.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(500));
        }

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xd7, 100_000.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 100_000.0), &op, &action, false)
            .await
            .expect("DOWN-reserved op must land on worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));

        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(200_000.0 - 50_000.0),
            "DOWN must FLOOR the reserve at declared/max_factor (100_000/2 = 50_000), NOT \
             collapse to the tiny p95 (500) — the worker's remaining must be 200_000−50_000 \
             = 150_000, the single-wrong-low bound the overcommit factor guarantees"
        );
    }

    /// (§3; #2497) DOWN packs: a low-variance over-declared key reserves its p95 BELOW
    /// declared, freeing capacity. p95 50_000 (20 @ 50_000 samples), declared 100_000,
    /// factor 4 (floor 25_000) → reserve 50_000 < declared 100_000.
    ///
    /// MUTATION: in the effective-compute, replace the DOWN branch result with
    /// `declared_kb` → remaining reads 100_000 (no packing) → this red-fails.
    #[nativelink_test]
    async fn down_overcommit_lowers_reservation_below_declared() {
        let wsm = BarrierWorkerStateManager::new();
        let scheduler = build_scheduler(wsm);
        scheduler.set_phase3_enforcement(false, true, 4.0, 604_800, false, 2000, 20000, false);
        let _rx_w = add_worker_with_memory_and_total(&scheduler, "W", 200_000.0, 200_000).await;

        // 20 samples @ 50_000 KiB → window p95 = 50_000 <= declared 100_000.
        for _ in 0..crate::resource_profile::PROFILE_MIN_SAMPLES {
            scheduler.resource_profile_record_sample(observe_key(), mem_only_sample(50_000));
        }

        let op = OperationId::default();
        let action = action_with_memory_and_baggage("W", 0xd8, 100_000.0);
        let (reserved, _tx, _msg) = scheduler
            .find_and_reserve_worker(&props_named_with_memory("W", 100_000.0), &op, &action, false)
            .await
            .expect("DOWN-reserved op must land on worker W");
        assert_eq!(reserved, WorkerId("W".to_string()));
        assert_eq!(
            scheduler.worker_min_prop(&WorkerId("W".to_string()), "memory_kb").await,
            Some(200_000.0 - 50_000.0),
            "DOWN must reserve the p95 (50_000) BELOW declared (100_000) → remaining \
             200_000−50_000=150_000 — this is where the packing comes from"
        );
    }

    /// (§3) DOWN is INERT at the default `overcommit_max_factor == 1.0`: the floor equals
    /// declared, so the reservation is byte-identical to the declared-only ledger even
